pub fn version_admitted(version: &str) -> bool {
    REVIEWED_BUILDS
        .iter()
        .any(|(reviewed, _, _)| *reviewed == version)
}
pub fn runtime_admitted(pin: &Pin) -> Result<()> {
    if pin.provider != Provider::Codex
        || !REVIEWED_BUILDS
            .iter()
            .any(|(version, sha256, _)| *version == pin.version && *sha256 == pin.sha256)
    {
        return Err(Error::Unavailable(
            "Codex build has no broker-only qualification; install the qualified build and run xcb doctor",
        ));
    }
    Ok(())
}

/// Accept the baked release builds and exact provider binaries that the
/// reviewed-builds catalog has admitted. The catalog is intentionally an
/// exact `(version, sha256)` allowlist: it makes compatible Codex updates
/// usable without waiting for an xcb release while keeping protocol changes,
/// unknown bytes, and explicitly denied builds unavailable.
pub fn runtime_admitted_with_catalog(root: &Path, pin: &Pin) -> Result<()> {
    if crate::catalog::denied(root, &pin.sha256) {
        return Err(Error::Unavailable(
            "Codex build is denied by the reviewed-builds catalog",
        ));
    }
    if runtime_admitted(pin).is_ok()
        || (pin.provider == Provider::Codex
            && crate::catalog::admitted(root, Provider::Codex, &pin.version, &pin.sha256))
    {
        return Ok(());
    }
    Err(Error::Unavailable(
        "Codex build has no broker-only qualification; install the qualified build and run xcb doctor",
    ))
}

/// Construction is restricted to checked runtime metadata. This binds the
/// catalog bytes; the host still owns OS confinement and live qualification.
#[derive(Debug, Clone)]
pub struct Admission {
    pub(crate) catalog_sha256: String,
    // Read by the launch path and its tests, which Windows builds refuse.
    #[cfg_attr(windows, allow(dead_code))]
    pub(crate) models: BTreeSet<String>,
}
#[derive(Debug)]
pub struct StaticCatalog {
    pub bytes: Vec<u8>,
    pub sha256: String,
    pub admission: Admission,
}

#[cfg(test)]
fn catalog_from_bytes(
    binary: &[u8],
    selected: Option<&str>,
    expected_sha256: &str,
) -> Result<StaticCatalog> {
    transform_catalog(
        catalog_source_from_bytes(binary, expected_sha256)?,
        selected,
        false,
    )
}

/// Locate and parse the bundled catalog inside the admitted executable. The
/// byte digest check stays here so every caller — cached or not — still
/// proves the exact installed bytes produced the catalog.
fn catalog_source_from_bytes(binary: &[u8], expected_sha256: &str) -> Result<Value> {
    if binary.len() > 512 * 1024 * 1024 || digest(binary) != expected_sha256 {
        return Err(Error::Unavailable(
            "Codex executable changed during catalog extraction",
        ));
    }
    let marker = b"{\n  \"models\":";
    let mut matches = binary
        .windows(marker.len())
        .enumerate()
        .filter(|(_, s)| *s == marker);
    let offset = matches
        .next()
        .map(|(i, _)| i)
        .ok_or(Error::Protocol("Codex bundled model catalog absent"))?;
    if matches.next().is_some() {
        return Err(Error::Protocol("ambiguous Codex model catalog"));
    }
    let end = (offset + 4 * 1024 * 1024).min(binary.len());
    let mut stream =
        serde_json::Deserializer::from_slice(&binary[offset..end]).into_iter::<Value>();
    stream
        .next()
        .ok_or(Error::Protocol("Codex model catalog absent"))?
        .map_err(Error::from)
}

fn transform_catalog(
    source: Value,
    selected: Option<&str>,
    native_cua: bool,
) -> Result<StaticCatalog> {
    let rows = source
        .get("models")
        .and_then(Value::as_array)
        .filter(|rows| !rows.is_empty() && rows.len() <= 256)
        .ok_or(Error::Protocol("Codex model catalog shape"))?;
    let mut seen = BTreeSet::new();
    let mut result = Vec::new();
    for row in rows {
        let slug = row
            .get("slug")
            .and_then(Value::as_str)
            .filter(|s| !s.is_empty() && s.len() <= 160)
            .ok_or(Error::Protocol("Codex model slug"))?;
        if !seen.insert(slug.to_owned()) {
            return Err(Error::Protocol("duplicate Codex model"));
        }
        // Unqualified models are deliberately absent from selectable metadata.
        if !QUALIFIED_MODELS.contains(&slug) || selected.is_some_and(|wanted| wanted != slug) {
            continue;
        }
        // The pinned model must already support Node REPL. Native CUA needs
        // that real capability in its turn metadata; never invent support
        // for an absent or disabled capability in an upstream model row.
        if native_cua && row.get("node_repl_disabled") != Some(&json!(false)) {
            continue;
        }
        for field in [
            "display_name",
            "supported_reasoning_levels",
            "shell_type",
            "visibility",
            "priority",
            "supported_in_api",
            "support_verbosity",
            "truncation_policy",
            "experimental_supported_tools",
        ] {
            if row.get(field).is_none() {
                return Err(Error::Protocol("incomplete Codex model metadata"));
            }
        }
        let mut row = row
            .as_object()
            .cloned()
            .ok_or(Error::Protocol("Codex model metadata"))?;
        // Exact 0.159.0's native children cannot use this broker lane:
        // fork_turns=none drops dynamic tools, while fork_turns=all requires
        // a persisted rollout that the ephemeral root deliberately lacks.
        // Keep delegation disabled until an exact-build probe demonstrates
        // inherited broker tools without changing that storage boundary.
        for (key, value) in [
            ("tool_mode", json!("direct")),
            ("shell_type", json!("disabled")),
            ("apply_patch_tool_type", Value::Null),
            ("experimental_supported_tools", json!([])),
            ("supports_search_tool", json!(false)),
            ("supports_experimental_context", json!(false)),
            ("multi_agent_version", json!("disabled")),
            ("node_repl_disabled", json!(!native_cua)),
        ] {
            row.insert(key.into(), value);
        }
        result.push(Value::Object(row));
    }
    if result.is_empty() {
        return Err(Error::Unavailable(if native_cua {
            "Codex model lacks pinned native-computer support"
        } else {
            "Codex model lacks exact-build broker-only qualification"
        }));
    }
    let models = result
        .iter()
        .filter_map(|r| r["slug"].as_str().map(str::to_owned))
        .collect();
    let bytes = serde_json::to_vec(&json!({"models":result}))?;
    let sha256 = digest(&bytes);
    Ok(StaticCatalog {
        admission: Admission {
            catalog_sha256: sha256.clone(),
            models,
        },
        bytes,
        sha256,
    })
}

/// The extracted bundled catalog kept under the private providers state dir
/// as `codex-catalog-<binary sha256>.json`, with the digests recorded inside.
/// The file is derived state: it is used only when the recorded executable
/// digest equals the verified pin's, and is otherwise re-derived.
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CachedCatalog {
    binary_sha256: String,
    source_sha256: String,
    source_base64: String,
}

fn catalog_cache_path(root: &Path, expected_sha256: &str) -> Result<PathBuf> {
    if !xcb_core::hex64(expected_sha256) {
        return Err(Error::Unavailable("executable digest is invalid"));
    }
    Ok(private::directory(&root.join("providers"))?
        .join(format!("codex-catalog-{expected_sha256}.json")))
}

fn cached_catalog_source(path: &Path, expected_sha256: &str) -> Option<Value> {
    let record: CachedCatalog =
        serde_json::from_slice(&private::read(path, 8 * 1024 * 1024).ok()?).ok()?;
    if record.binary_sha256 != expected_sha256 {
        return None;
    }
    let source = base64::engine::general_purpose::STANDARD
        .decode(record.source_base64.as_bytes())
        .ok()?;
    if source.len() > 4 * 1024 * 1024 || digest(&source) != record.source_sha256 {
        return None;
    }
    serde_json::from_slice(&source).ok()
}

fn store_catalog_source(path: &Path, expected_sha256: &str, source: &Value) -> Result<()> {
    let source = serde_json::to_vec(source)?;
    let record = CachedCatalog {
        binary_sha256: expected_sha256.to_owned(),
        source_sha256: digest(&source),
        source_base64: base64::engine::general_purpose::STANDARD.encode(source),
    };
    let bytes = serde_json::to_vec_pretty(&record)?;
    match private::read(path, 8 * 1024 * 1024) {
        Ok(old) => private::replace(path, &bytes, &digest(old)),
        Err(Error::Io(error)) if error.kind() == std::io::ErrorKind::NotFound => {
            private::create(path, &bytes)
        }
        // A cache file that fails custody is left alone and skipped; the
        // catalog is always re-derivable from the executable.
        Err(_) => Ok(()),
    }
}

/// Reads only the admitted executable, never the owner's model cache or auth.
/// No copied prompts or catalog from another Codex version are shipped by xcb.
/// The extracted catalog is cached under `root/providers/` keyed by the exact
/// executable digest, so a turn does not re-scan the binary.
pub fn static_catalog(root: &Path, pin: &Pin, selected: Option<&str>) -> Result<StaticCatalog> {
    runtime_admitted_with_catalog(root, pin)?;
    static_catalog_bound(root, pin, selected, &pin.sha256)
}

/// Only the launcher with an admitted native CUA proxy uses this catalog.
/// It retains pinned Node REPL support while leaving all other native tool
/// restrictions identical to the normal broker catalog.
#[cfg(target_os = "macos")]
pub(crate) fn static_catalog_with_native(
    root: &Path,
    pin: &Pin,
    selected: Option<&str>,
) -> Result<StaticCatalog> {
    runtime_admitted(pin)?;
    static_catalog_bound_mode(root, pin, selected, &pin.sha256, true)
}

/// The extraction path, bound to an explicit expected executable digest so a
/// synthetic build can exercise it in tests. Production admission always
/// first binds the version/digest pair through `static_catalog`.
pub(crate) fn static_catalog_bound(
    root: &Path,
    pin: &Pin,
    selected: Option<&str>,
    expected_sha256: &str,
) -> Result<StaticCatalog> {
    static_catalog_bound_mode(root, pin, selected, expected_sha256, false)
}

fn static_catalog_bound_mode(
    root: &Path,
    pin: &Pin,
    selected: Option<&str>,
    expected_sha256: &str,
    native_cua: bool,
) -> Result<StaticCatalog> {
    if pin.provider != Provider::Codex || pin.sha256 != expected_sha256 {
        return Err(Error::Unavailable("Codex build is not the admitted build"));
    }
    pin.verify()?;
    let cache = catalog_cache_path(root, expected_sha256).ok();
    if let Some(source) = cache
        .as_deref()
        .and_then(|path| cached_catalog_source(path, expected_sha256))
    {
        return transform_catalog(source, selected, native_cua);
    }
    let mut bytes = Vec::new();
    std::fs::File::open(&pin.executable)?
        .take(512 * 1024 * 1024 + 1)
        .read_to_end(&mut bytes)?;
    let source = catalog_source_from_bytes(&bytes, expected_sha256)?;
    pin.verify()?;
    if let Some(path) = cache {
        let _ = store_catalog_source(&path, expected_sha256, &source);
    }
    #[cfg(test)]
    CATALOG_EXTRACTIONS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    transform_catalog(source, selected, native_cua)
}

/// Binary scans that produced a catalog, for cache tests.
#[cfg(test)]
static CATALOG_EXTRACTIONS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

#[cfg(all(test, unix))]
pub(crate) fn catalog_extractions() -> usize {
    CATALOG_EXTRACTIONS.load(std::sync::atomic::Ordering::Relaxed)
}

