/// The host protects both this file and the catalog against provider writes.
/// Automatic review selects the reviewer; it does not widen the read-only
/// sandbox or admit native callbacks outside the host broker.
pub fn configuration(catalog_path: &Path) -> Result<String> {
    configuration_with_native(catalog_path, None)
}

pub(crate) fn configuration_with_native(
    catalog_path: &Path,
    native: Option<&Value>,
) -> Result<String> {
    let path = catalog_path
        .to_str()
        .filter(|s| {
            catalog_path.is_absolute() && s.len() <= 4096 && !s.chars().any(char::is_control)
        })
        .ok_or(Error::Protocol("Codex catalog path"))?;
    let mut lines = vec![format!(
        "model_catalog_json = {}",
        serde_json::to_string(path)?
    )];
    lines.extend(
        [
            "model_provider = \"openai\"",
            "forced_login_method = \"chatgpt\"",
            "cli_auth_credentials_store = \"file\"",
            "mcp_oauth_credentials_store = \"file\"",
            "approval_policy = \"on-request\"",
            "approvals_reviewer = \"auto_review\"",
            "sandbox_mode = \"read-only\"",
            "web_search = \"disabled\"",
            "project_doc_max_bytes = 0",
            "check_for_update_on_startup = false",
            "allow_login_shell = false",
            "notify = []",
            "mcp_servers = {}",
            "plugins = {}",
            "[shell_environment_policy]",
            "inherit = \"none\"",
            "[analytics]",
            "enabled = false",
            "[feedback]",
            "enabled = false",
            "[history]",
            "persistence = \"none\"",
            "[features]",
        ]
        .map(str::to_owned),
    );
    lines.extend(
        ACCOUNT_FEATURES
            .iter()
            // Feature names can contain dots; quote each TOML key so a
            // disabled feature cannot become an unrelated nested table.
            .map(|name| {
                format!(
                    "{} = false",
                    serde_json::to_string(name).expect("feature name")
                )
            }),
    );
    lines.extend(
        [
            "[apps._default]",
            "enabled = false",
            "destructive_enabled = false",
            "open_world_enabled = false",
            "[orchestrator.skills]",
            "enabled = false",
            "[skills]",
            "include_instructions = false",
            "[skills.bundled]",
            "enabled = false",
            "",
        ]
        .map(str::to_owned),
    );
    if let Some(server) = native {
        lines.retain(|line| line != "mcp_servers = {}");
        validate_native_definition(server)?;
        lines.push("[mcp_servers.cua_repl]".into());
        for key in ["command", "args", "enabled", "enabled_tools"] {
            lines.push(format!("{key} = {}", serde_json::to_string(&server[key])?));
        }
        let environment = server["env"]
            .as_object()
            .ok_or(Error::Protocol("Codex native environment"))?;
        lines.push(format!(
            "env = {{ {} }}",
            environment
                .iter()
                .map(|(name, value)| {
                    Ok(format!(
                        "{} = {}",
                        serde_json::to_string(name)?,
                        serde_json::to_string(value)?
                    ))
                })
                .collect::<Result<Vec<_>>>()?
                .join(", ")
        ));
        lines.push(String::new());
    }
    Ok(lines.join("\n"))
}

fn validate_native_definition(server: &Value) -> Result<()> {
    super::closed(
        server,
        &["command", "args", "env", "enabled", "enabled_tools"],
    )?;
    let command = server["command"]
        .as_str()
        .ok_or(Error::Protocol("Codex native command"))?;
    let env = server["env"]
        .as_object()
        .ok_or(Error::Protocol("Codex native environment"))?;
    super::require(
        Path::new(command).is_absolute()
            && command.len() <= 4096
            && !command.chars().any(char::is_control)
            && server["args"] == json!(["native-mcp-stdio"])
            && server["enabled"] == true
            && server["enabled_tools"].as_array().is_some_and(|tools| {
                !tools.is_empty()
                    && tools.len() <= 3
                    && tools.contains(&json!("js"))
                    && tools
                        .iter()
                        .all(|tool| matches!(tool.as_str(), Some("js" | "js_reset" | "turn_ended")))
                    && tools
                        .iter()
                        .filter_map(Value::as_str)
                        .collect::<BTreeSet<_>>()
                        .len()
                        == tools.len()
            })
            && env.len() == 2
            && env
                .get("XCB_MCP_SOCKET")
                .and_then(Value::as_str)
                .is_some_and(|path| {
                    Path::new(path).is_absolute()
                        && path.len() <= 100
                        && !path.chars().any(char::is_control)
                })
            && env
                .get("XCB_MCP_TOKEN")
                .and_then(Value::as_str)
                .is_some_and(|token| {
                    (32..=128).contains(&token.len())
                        && token
                            .bytes()
                            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
                }),
        "Codex native tool definition changed",
    )
}

pub fn thread_configuration(effort: Option<&str>) -> Value {
    let features: serde_json::Map<String, Value> = ACCOUNT_FEATURES
        .iter()
        .chain(EXTRA_FEATURES)
        .map(|name| (name.to_string(), json!(false)))
        .collect();
    let mut config = json!({"features":features,"tools":{"experimental_request_user_input":{"enabled":false},"update_plan":{"enabled":false}},"agents":{"enabled":false},"approvals_reviewer":"auto_review"});
    if let Some(effort) = effort {
        config["model_reasoning_effort"] = json!(effort);
    }
    config
}

#[cfg(all(test, unix))]
pub(crate) fn validate_config(value: &Value, catalog_path: &Path) -> Result<()> {
    validate_config_with_native(value, catalog_path, None)
}

pub(crate) fn validate_config_with_native(
    value: &Value,
    catalog_path: &Path,
    native: Option<&Value>,
) -> Result<()> {
    let c = value
        .get("config")
        .and_then(Value::as_object)
        .ok_or(Error::Protocol("Codex config response"))?;
    for (key, expected) in [
        ("model_provider", json!("openai")),
        ("forced_login_method", json!("chatgpt")),
        ("cli_auth_credentials_store", json!("file")),
        ("mcp_oauth_credentials_store", json!("file")),
        ("approval_policy", json!("on-request")),
        ("approvals_reviewer", json!("auto_review")),
        ("sandbox_mode", json!("read-only")),
        ("web_search", json!("disabled")),
        ("project_doc_max_bytes", json!(0)),
        ("check_for_update_on_startup", json!(false)),
        ("allow_login_shell", json!(false)),
        ("notify", json!([])),
        ("plugins", json!({})),
        ("model_providers", json!({})),
        ("model_catalog_json", json!(catalog_path)),
    ] {
        if c.get(key) != Some(&expected) {
            return Err(Error::Protocol("Codex isolated configuration mismatch"));
        }
    }
    match native {
        None if c.get("mcp_servers") != Some(&json!({})) => {
            return Err(Error::Protocol("Codex unexpected native servers"));
        }
        Some(expected) => {
            validate_native_definition(expected)?;
            let servers = c
                .get("mcp_servers")
                .and_then(Value::as_object)
                .filter(|servers| servers.len() == 1)
                .ok_or(Error::Protocol("Codex native server inventory changed"))?;
            let actual = servers
                .get("cua_repl")
                .ok_or(Error::Protocol("Codex native server missing"))?;
            let mut expected = expected.clone();
            expected["environment_id"] = json!("local");
            expected["tool_timeout_sec"] = Value::Null;
            if actual != &expected {
                return Err(Error::Protocol("Codex native server controls changed"));
            }
        }
        None => {}
    }
    if c.get("chatgpt_base_url") != Some(&json!("https://chatgpt.com/backend-api/")) {
        return Err(Error::Protocol("Codex ChatGPT endpoint changed"));
    }
    for key in [
        "instructions",
        "developer_instructions",
        "compact_prompt",
        "model_instructions_file",
        "experimental_compact_prompt_file",
        "openai_base_url",
    ] {
        if c.get(key).is_some_and(|v| !v.is_null()) {
            return Err(Error::Protocol("Codex inherited instructions or endpoint"));
        }
    }
    let v = Value::Object(c.clone());
    for (pointer, expected) in [
        ("/shell_environment_policy/inherit", json!("none")),
        ("/analytics/enabled", json!(false)),
        ("/feedback/enabled", json!(false)),
        ("/history/persistence", json!("none")),
        ("/skills/include_instructions", json!(false)),
        ("/skills/bundled/enabled", json!(false)),
        ("/orchestrator/skills/enabled", json!(false)),
        ("/apps/_default/enabled", json!(false)),
        ("/apps/_default/destructive_enabled", json!(false)),
        ("/apps/_default/open_world_enabled", json!(false)),
    ] {
        if v.pointer(pointer) != Some(&expected) {
            return Err(Error::Protocol("Codex configuration controls mismatch"));
        }
    }
    if v["apps"].as_object().is_none_or(|a| a.len() != 1) {
        return Err(Error::Protocol("Codex inherited apps"));
    }
    for name in ACCOUNT_FEATURES {
        if v["features"].get(name) != Some(&json!(false)) {
            return Err(Error::Protocol("Codex account feature enabled"));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn catalog_preserves_native_protocol_and_metadata() {
        let source = fixture_catalog_source();
        let catalog = transform_catalog(source, Some("gpt-6-astra"), false).unwrap();
        let row: Value = serde_json::from_slice(&catalog.bytes).unwrap();
        assert_eq!(
            row["models"][0]["model_messages"]["instructions_template"],
            "retained"
        );
        assert_eq!(row["models"][0]["use_responses_lite"], true);
        assert_eq!(row["models"][0]["shell_type"], "disabled");
        assert_eq!(row["models"][0]["multi_agent_version"], "disabled");
        assert_eq!(row["models"][0]["experimental_supported_tools"], json!([]));
        assert!(transform_catalog(row, Some("unqualified"), false).is_err());
    }
    #[test]
    fn untested_builds_and_forged_catalogs_are_not_admitted() {
        assert!(version_admitted(VERSION));
        assert!(!version_admitted("0.155.1"));
        assert!(!version_admitted("0.155.0-alpha.2.6"));
        assert!(catalog_from_bytes(b"{\n  \"models\":[]}", None, BINARY_SHA256).is_err());
    }

    #[test]
    fn supported_versions_are_bound_to_their_own_executable_and_schema() {
        for (version, sha256, schema) in REVIEWED_BUILDS {
            assert!(version_admitted(version));
            assert_eq!(schema.len(), 64);
            let mut pin = Pin {
                provider: Provider::Codex,
                executable: "/synthetic/codex".into(),
                sha256: (*sha256).into(),
                version: (*version).into(),
                host_sha256: "0".repeat(64),
                observed_at_ms: 0,
            };
            runtime_admitted(&pin).unwrap();
            pin.sha256 = "f".repeat(64);
            assert!(runtime_admitted(&pin).is_err());
            pin.sha256 = (*sha256).into();
            pin.version = "0.0.0".into();
            assert!(runtime_admitted(&pin).is_err());
        }
        // Distinct versions may share a schema when the generated schema is
        // unchanged; version and executable digests stay unique.
        let versions: BTreeSet<_> = REVIEWED_BUILDS.iter().map(|(v, _, _)| v).collect();
        let executables: BTreeSet<_> = REVIEWED_BUILDS.iter().map(|(_, s, _)| s).collect();
        assert_eq!(versions.len(), REVIEWED_BUILDS.len());
        assert_eq!(executables.len(), REVIEWED_BUILDS.len());
    }

    #[test]
    fn native_catalog_retains_only_pinned_node_support_and_no_other_authority() {
        let source = fixture_catalog_source();
        let normal = transform_catalog(source.clone(), Some("gpt-6-astra"), false).unwrap();
        let native = transform_catalog(source.clone(), Some("gpt-6-astra"), true).unwrap();
        assert_ne!(normal.sha256, native.sha256);
        assert_eq!(native.admission.catalog_sha256, digest(&native.bytes));
        let normal: Value = serde_json::from_slice(&normal.bytes).unwrap();
        let mut native: Value = serde_json::from_slice(&native.bytes).unwrap();
        assert_eq!(normal["models"][0]["node_repl_disabled"], true);
        assert_eq!(native["models"][0]["node_repl_disabled"], false);
        native["models"][0]["node_repl_disabled"] = json!(true);
        assert_eq!(normal, native);
        assert_eq!(native["models"][0]["shell_type"], "disabled");
        assert_eq!(
            native["models"][0]["experimental_supported_tools"],
            json!([])
        );
        assert_eq!(native["models"][0]["multi_agent_version"], "disabled");
        assert!(native["models"][0]["apply_patch_tool_type"].is_null());
        for unsupported in [json!(true), Value::Null, json!("false")] {
            let mut changed = source.clone();
            changed["models"][0]["node_repl_disabled"] = unsupported;
            assert!(transform_catalog(changed, Some("gpt-6-astra"), true).is_err());
        }
    }

    #[test]
    fn catalog_admission_reaches_the_launch_gate_without_becoming_fail_open() {
        let directory = tempfile::tempdir().unwrap();
        let root = xcb_core::canonical(directory.path()).unwrap();
        private::directory(&root.join("providers")).unwrap();
        let digest = "a".repeat(64);
        private::create(
            &root.join("providers/catalog.json"),
            serde_json::json!({
                "version": 1,
                "codex": [{"version": "0.160.0", "sha256": digest.clone()}],
            })
            .to_string()
            .as_bytes(),
        )
        .unwrap();
        let pin = Pin {
            provider: Provider::Codex,
            executable: "/synthetic/codex".into(),
            sha256: digest.clone(),
            version: "0.160.0".into(),
            host_sha256: "0".repeat(64),
            observed_at_ms: 0,
        };
        runtime_admitted_with_catalog(&root, &pin).unwrap();

        let mut unknown = pin.clone();
        unknown.version = "0.160.1".into();
        assert!(runtime_admitted_with_catalog(&root, &unknown).is_err());

        private::replace(
            &root.join("providers/catalog.json"),
            serde_json::json!({
                "version": 1,
                "codex": [{"version": "0.160.0", "sha256": digest.clone()}],
                "deny": {"codex": [digest.clone()]},
            })
            .to_string()
            .as_bytes(),
            &crate::digest(
                &private::read(&root.join("providers/catalog.json"), 64 * 1024).unwrap(),
            ),
        )
        .unwrap();
        assert!(runtime_admitted_with_catalog(&root, &pin).is_err());
    }

    // Unix catalog paths; Codex launch is refused on Windows.
    #[cfg(unix)]
    #[test]
    fn background_features_are_disabled_as_literal_toml_keys() {
        let config = configuration(Path::new("/synthetic/catalog.json")).unwrap();
        for name in ["daemon_auto_start", "guardianv2.thread_context"] {
            assert!(config.contains(&format!("\"{name}\" = false")));
            assert_eq!(thread_configuration(None)["features"][name], false);
        }
    }

    #[cfg(unix)]
    #[test]
    fn catalog_cache_is_keyed_by_the_exact_executable_digest() {
        use std::os::unix::fs::PermissionsExt;
        let directory = tempfile::tempdir().unwrap();
        let root = xcb_core::canonical(directory.path()).unwrap();
        let executable = root.join("codex");
        let mut bytes = b"synthetic codex binary\n".to_vec();
        bytes.extend(serde_json::to_vec_pretty(&fixture_catalog_source()).unwrap());
        bytes.push(0);
        std::fs::write(&executable, &bytes).unwrap();
        std::fs::set_permissions(&executable, std::fs::Permissions::from_mode(0o755)).unwrap();
        let executable = xcb_core::canonical(executable).unwrap();
        let sha256 = crate::process::executable_digest(&executable).unwrap();
        let (_, host_sha256) = crate::process::host_identity().unwrap();
        let pin = Pin {
            provider: Provider::Codex,
            executable,
            sha256: sha256.clone(),
            version: VERSION.into(),
            host_sha256,
            observed_at_ms: crate::now_ms(),
        };
        let cache = root
            .join("providers")
            .join(format!("codex-catalog-{sha256}.json"));
        let extracted = catalog_extractions();
        let first = static_catalog_bound(&root, &pin, Some("gpt-6-astra"), &sha256).unwrap();
        assert!(cache.is_file());
        let second = static_catalog_bound(&root, &pin, Some("gpt-6-astra"), &sha256).unwrap();
        assert_eq!(first.sha256, second.sha256);
        assert_eq!(first.bytes, second.bytes);
        assert_eq!(catalog_extractions() - extracted, 1);
        let native =
            static_catalog_bound_mode(&root, &pin, Some("gpt-6-astra"), &sha256, true).unwrap();
        assert_ne!(native.sha256, first.sha256);
        assert_eq!(catalog_extractions() - extracted, 1);
        assert_eq!(
            static_catalog_bound(&root, &pin, Some("gpt-6-astra"), &sha256)
                .unwrap()
                .sha256,
            first.sha256
        );
        // A corrupted cache file is derived state: it is ignored, re-extracted,
        // and republished, never admitted.
        std::fs::write(&cache, b"not a catalog").unwrap();
        let third = static_catalog_bound(&root, &pin, Some("gpt-6-astra"), &sha256).unwrap();
        assert_eq!(third.sha256, first.sha256);
        assert_eq!(catalog_extractions() - extracted, 2);
    }
}
